SELECT region, CASE WHEN sqft >= 17904 THEN 'high' WHEN sqft >= 6057 THEN 'mid' ELSE 'low' END AS sqft_bucket, DATE_TRUNC('MONTH', opened_date) AS opened_month, ROUND(STDDEV(sqft), 2) AS stddev_sqft, SORT_ARRAY(COLLECT_SET(region)) AS region_list FROM stores WHERE store_name IS NOT NULL AND MONTH(opened_date) IN (3, 7, 11) AND region = 'North' GROUP BY region, CASE WHEN sqft >= 17904 THEN 'high' WHEN sqft >= 6057 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', opened_date) ORDER BY sqft_bucket DESC
